141	void AsynchronousMetrics::openBlockDevices()
142	{
143	    LOG_TRACE(log, "Scanning /sys/block");
144	
145	    if (!std::filesystem::exists("/sys/block"))
146	        return;
147	
148	    block_devices_rescan_delay.restart();
149	
150	    block_devs.clear();
151	
152	    for (const auto & device_dir : std::filesystem::directory_iterator("/sys/block"))
153	    {
154	        String device_name = device_dir.path().filename();
155	
156	        /// We are not interested in loopback devices.
157	        if (device_name.starts_with("loop"))
158	            continue;
159	
160	        std::unique_ptr<ReadBufferFromFilePRead> file = openFileIfExists(device_dir.path() / "stat");
161	        if (!file)
162	            continue;
163	
164	        block_devs[device_name] = std::move(file);
165	    }
166	}
